<?php
require __DIR__.'/auth.php';
requireLogin();
$user=currentUser();
$today=date('Y-m-d');
$schedule=[
 ['08:00','09:00','Breakfast','Idli / dosa / chapati + egg','🍳'],
 ['10:30','11:00','Morning Snack','Banana or another fruit','🍌'],
 ['12:00','13:00','Lunch','Rice + vegetables + fish/chicken/egg/dal','🍚'],
 ['16:30','17:00','Evening Snack','Milk + guava + peanuts/almonds','🥛'],
 ['20:00','21:00','During Duty','2 boiled eggs + banana','🥚'],
 ['22:15','22:45','Dinner','Rice + fish/egg/chicken + vegetables','🍛']
];
$allowedMealNames=array_column($schedule,2);
$stmt=$db->prepare('SELECT id,lunch_date,food_item,quantity,notes,meal_type,meal_time,recorded_time FROM lunches WHERE user_id=? AND lunch_date=? ORDER BY meal_time ASC,id DESC');
$stmt->execute([$_SESSION['user_id'],$today]);$lunches=$stmt->fetchAll();
$stmt=$db->prepare('SELECT COUNT(*) FROM lunches WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$totalAll=(int)$stmt->fetchColumn();
$stmt=$db->prepare('SELECT COUNT(DISTINCT lunch_date) FROM lunches WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$daysLogged=(int)$stmt->fetchColumn();
$todayMeals=array_fill_keys($allowedMealNames,false);foreach($lunches as $row){$todayMeals[$row['meal_type']??'Lunch']=true;}
$completedMeals=count(array_filter($todayMeals));$mealProgress=(int)round(($completedMeals/count($allowedMealNames))*100);
function displayDate(string $iso):string{$t=strtotime($iso);return $t?date('d-m-Y',$t):$iso;}
function displayTime(?string $iso):string{$t=$iso?strtotime($iso):false;return $t?date('h:i A',$t):'';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f172a"><meta name="description" content="Personal meal tracker with food history, reports and meal reminders."><link rel="manifest" href="manifest.json"><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/app.css"><title>Lunch Food Log</title><style>.hero-row{display:flex;align-items:center;gap:14px}.app-logo{width:70px;height:70px;border-radius:18px;box-shadow:0 8px 20px rgba(0,0,0,.25)}.progress{height:9px;background:#e5e7eb;border-radius:99px;overflow:hidden;margin-top:9px}.progress>span{display:block;height:100%;background:#2563eb;border-radius:99px}.meal.done{border-color:#bbf7d0;background:#f0fdf4}.done-mark{font-size:11px;color:#15803d;font-weight:900}.entry-actions form{margin:0}.logout-btn{width:auto!important;margin:0!important}.quick-note{font-size:12px;color:var(--muted);margin:0}.search-wrap{margin-bottom:12px}.search-wrap input{background:#f8fafc}.empty{padding:25px 10px}.mobile-nav{padding-bottom:calc(7px + env(safe-area-inset-bottom))}@media(max-width:600px){.hero-row{align-items:flex-start}.app-logo{width:58px;height:58px;border-radius:15px}.hero{padding:19px}.hero h1{font-size:25px}}</style></head><body>
